Definition iarm_1RB0RC_0LC1LA_0LB1RD_1LB0RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0RC_0LC1LA_0LB1RD_1LB0RD
  | 0, 1 => iarm0_1_1RB0RC_0LC1LA_0LB1RD_1LB0RD
  | 0, 2 => iarm0_2_1RB0RC_0LC1LA_0LB1RD_1LB0RD
  | _, _ => iarm0_0_1RB0RC_0LC1LA_0LB1RD_1LB0RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB0RC_0LC1LA_0LB1RD_1LB0RD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB0RC_0LC1LA_0LB1RD_1LB0RD
  | 2, 0 => farm2_0_1RB0RC_0LC1LA_0LB1RD_1LB0RD
  | 3, 0 => farm3_0_1RB0RC_0LC1LA_0LB1RD_1LB0RD
  | _, _ => farm1_0_1RB0RC_0LC1LA_0LB1RD_1LB0RD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0RC_0LC1LA_0LB1RD_1LB0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | 3, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB0RC_0LC1LA_0LB1RD_1LB0RD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | 3, 0 => 2 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB0RC_0LC1LA_0LB1RD_1LB0RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 1;SWinR 3;SWinL 3]
  | 1, (StA, S1) => [SWin 1;SWinR 3;SWinL 5]
  | 1, (StB, S0) => [SWinR 3]
  | 1, (StB, S1) => [SWinR 6]
  | 1, (StC, S0) => [SWinR 6;SWinL 6;SWinR 120;SWinR 120]
  | 1, (StC, S1) => []
  | 1, (StD, S0) => [SWinR 2]
  | 1, (StD, S1) => [SWin 1]
  | 2, (StA, S0) => [SWin 2;SCycR 2;SWinR 2;SCycL 2 0;SWinL 3]
  | 2, (StA, S1) => [SWin 2;SCycR 2;SWinR 2;SCycL 2 0;SWinL 5]
  | 2, (StB, S0) => [SWin 2;SCycR 2;SWinR 2]
  | 2, (StB, S1) => [SWin 2;SCycR 2;SWinR 2;SCycL 2 0;SWin 2]
  | 2, (StC, S0) => [SWin 2;SCycR 2;SWinR 2;SCycL 2 0;SWin 1]
  | 2, (StC, S1) => [SWin 0]
  | 2, (StD, S0) => [SWin 2;SCycR 2;SWinR 1]
  | 2, (StD, S1) => [SWin 1]
  | 3, (StA, S0) => [SWin 3;SCycR 2;SWinR 2;SCycL 2 0;SWinL 6]
  | 3, (StA, S1) => [SWin 3;SCycR 2;SWinR 2;SCycL 2 0;SWinL 8]
  | 3, (StB, S0) => [SWin 3;SCycR 2;SWinR 2]
  | 3, (StB, S1) => [SWin 3;SCycR 2;SWinR 2;SCycL 2 0;SWin 5]
  | 3, (StC, S0) => [SWin 3;SCycR 2;SWinR 2;SCycL 2 0;SWin 1]
  | 3, (StC, S1) => []
  | 3, (StD, S0) => [SWin 3;SCycR 2;SWinR 1]
  | 3, (StD, S1) => [SWin 1]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
