Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1LD_1RC0RB_0LA1LA_0LD0RC : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1LD_1RC0RB_0LA1LA_0LD0RC. Qed.

